def build_agent(sandbox):
    # Main buoyant beam for stability and buoyancy
    main_beam = sandbox.add_beam(x=4.0, y=0.5, width=2.0, height=0.6, density=350)
    sandbox.set_material_properties(main_beam, restitution=0.05)

    # Front paddles for thrust
    paddles = []
    for i, x in enumerate([4.5, 5.5, 6.5]):
        b = sandbox.add_beam(x, 0.5, 0.4, 0.4, density=350)
        paddles.append(b)
        sandbox.add_joint(main_beam, b, (x, 0.5), type='rigid')
        sandbox.set_material_properties(b, restitution=0.05)

    return main_beam

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    THRUST_F = 520.0
    LIFT_F = 400.0
    in_danger_zone = (16.5 <= front_x <= 19.5)

    # Apply lift to the main beam in the deep channel
    if in_danger_zone:
        sandbox.apply_force(agent_body, 0.0, LIFT_F, step_count=step_count)

    # Apply thrust to front paddles with staggered cooldown
    paddles = [b for b in sandbox.bodies if b is not agent_body]
    for i, b in enumerate(paddles):
        if not b.active:
            continue
        if step_count % 3 == i % 3:
            sandbox.apply_force(b, THRUST_F, 0.0, step_count=step_count)
